import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../types";
import { SlotEventInfo } from "./SlotEventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({ title, children }: { title: string; children: React.ReactNode }) => (
    <div>
      <h1>{title}</h1>
      {children}
    </div>
  ),
}));

const slotEvent: ConversationEvent = {
  id: "e1",
  conversationEventType: ConversationEventType.Slot,
  name: "card_replace.replacement_reason",
  slotValue: "stolen",
  actionText: "",
  flowId: "",
  stepId: "",
  timestamp: "2020-01-01T00:00:00.000Z",
  originalTimestamp: 0,
  metadata: { parseData: {} },
  __typename: "ConversationEvent",
};

describe("SlotEventInfo", () => {
  it("uses the slot vocabulary", () => {
    renderWithProviders(<SlotEventInfo event={slotEvent} onClose={() => undefined} />);
    expect(screen.getByRole("heading", { name: "Slot event" })).toBeInTheDocument();
    expect(screen.getByText("Slot name")).toBeInTheDocument();
  });
});
